CREATE OR REPLACE FUNCTION public.completar_negocio_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.negocio_id is null then
        new.negocio_id := public.negocio_actual_id();
    end if;

    if not public.es_miembro_negocio(new.negocio_id) then
        raise exception 'No autorizado para este negocio';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.stock_sucursal_recalcular_total_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform public.recalcular_stock_total_producto_v1(
        coalesce(new.producto_id, old.producto_id)
    );
    return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.vendify_limite_productos_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform public.validar_limite_plan_v1(
        new.negocio_id,'productos',1
    );
    return new;
end;
$function$
